<?php require_once __DIR__ . '/_boot.php'; $rows=[]; try { $st=db()->prepare("SELECT ph.*, p.name finished_name FROM production_headers ph LEFT JOIN products p ON p.id=ph.finished_product_id WHERE ph.branch_id=? ORDER BY ph.id DESC LIMIT 200"); $st->execute([$unitId]); $rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[]; } catch(Throwable $e) { $err=$e->getMessage(); } ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Produksi Dapur</title><link rel="icon" href="<?php echo e(favicon_url()); ?>"><link rel="stylesheet" href="<?php echo e(asset_url('assets/app.css')); ?>"><style><?php echo $customCss; ?></style></head><body><div class="container"><?php include __DIR__ . '/_sidebar.php'; ?><div class="main"><div class="topbar"><button class="btn" data-toggle-sidebar type="button">Menu</button><strong>Produksi BOM Dapur</strong></div><div class="content"><div class="card"><p>Produksi BOM untuk dapur/unit ini. Form input detail tetap dapat memakai modul produksi lama sampai form baru final; data produksi baru diarahkan per unit dapur.</p><a class="btn" href="<?php echo e(base_url('admin/production.php?branch_id='.$unitId)); ?>">Input Produksi</a></div><div class="card"><table class="table"><thead><tr><th>Tanggal</th><th>No</th><th>Produk Jadi</th><th>Qty</th><th>Status</th><th>Mode</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?php echo e($r['production_date']); ?></td><td><?php echo e($r['production_no']); ?></td><td><?php echo e($r['finished_name'] ?? '-'); ?></td><td><?php echo e(format_qty($r['qty_to_produce'])); ?></td><td><?php echo e($r['status']); ?></td><td><?php echo e($r['mode_source']); ?></td></tr><?php endforeach; if(empty($rows)): ?><tr><td colspan="6">Belum ada produksi.</td></tr><?php endif; ?></tbody></table></div></div></div></div><script src="<?php echo e(asset_url('assets/app.js')); ?>"></script></body></html>
